/**
 * dsh-notifier 客户端 —— 文案绑定。
 *
 * 翻译函数必须能在 apply 期被 locale 服务重绑（切语言时订阅回调会再绑一次），而它又被全文
 * 一百多处调用点引用。用 const 容器承载「当前绑定」把这份可变状态显式化：页面级共享是刻意的
 * ——一个页面只有一份语言。
 *
 * 未装配时回落 key 本体：宿主没提供 locale 服务时界面照常渲染（显示 key 而不是崩）。
 */

export type Translate = (key: string, params?: Record<string, unknown>) => string;

/** 未装配时的回落：key 即文案。 */
const fallbackTranslate: Translate = (key) => String(key);

const binding: { current: Translate } = { current: fallbackTranslate };

/** 装配 / 重绑翻译函数（apply 期与 locale 订阅回调调用）。 */
export function bindTranslate(next: Translate): void {
  binding.current = next;
}

/** 当前翻译函数。 */
export const t: Translate = (key, params) => binding.current(key, params);

packages/dsh-notifier/src/client/notify/.source:
/**
 * dsh-notifier 客户端 —— 音频出口（解锁、自播、节流）。
 *
 * 这一份是**跨实例共享**的：AudioContext 与节流窗口若按实例各建一份，同一页面重复挂载后
 * 会出现两个上下文、两套节流，表现为同一帧响两次或该响的不响。故用 `const` 单例承载闭包状态
 * ——不是模块级 `let`（那会被 forbid-module-state-src 判红，而且表达不了「共享」这件事）。
 *
 * 时钟与构造器从端口进来，于是「未解锁 / 被挂起 / 被拒绝 / 不支持」四条分支都能在 node 里
 * 用假 AudioContext 跑出来——原先一条都测不到。
 */
import { FOLLOW_SYSTEM_TONE, TONES } from "../../shared/interface.ts";

/**
 * 音频面的原始事实（只有页面读得到；判定在 capabilities.ts）。
 *
 * 形状定义在**生产者**这一侧：本模块的 facts() 产出它，判定面（capabilities.ts 的 audioStateOf
 * 与 ClientFacts）只是消费它。反过来声明会让生产者 import 消费者，依赖方向反了——本文件里
 * 其它端口类型（AudioContextLike / AudioEngine）本来就是这么定义的。
 */
export interface AudioFacts {
  /** `window.AudioContext` 是否存在——只有它不存在才是「Web Audio 不可用」。 */
  supported: boolean;
  /** 当前 state；`null` = 尚未构造（用户还没点过页面）。 */
  state: "running" | "suspended" | "closed" | null;
  /** 是否曾成功跑到 `running`（已解锁的唯一凭据）。 */
  hasEverRun: boolean;
  /** 最近一次 `resume()` 是否被 reject（浏览器明确拒绝，而不是「还没轮到」）。 */
  resumeRejected: boolean;
}

/** 统一播放节流窗口（毫秒）：覆盖全部自播路径（通知音 + 只响不弹），试听不经本门。 */
export const PLAY_THROTTLE_MS = 1500;

/** 音频上下文的最小可判别面（真实 AudioContext 与测试替身都实现它）。 */
export interface AudioContextLike {
  state: string;
  currentTime: number;
  destination: unknown;
  createBuffer(channels: number, length: number, sampleRate: number): unknown;
  createBufferSource(): {
    buffer: unknown;
    connect(target: unknown): void;
    start(when: number): void;
  };
  createOscillator(): {
    type: string;
    frequency: { value: number };
    connect(target: unknown): void;
    start(when: number): void;
    stop(when: number): void;
  };
  createGain(): {
    gain: {
      setValueAtTime(value: number, when: number): void;
      exponentialRampToValueAtTime(value: number, when: number): void;
    };
    connect(target: unknown): void;
  };
  resume(): Promise<void> | void;
}

export interface AudioEnginePorts {
  /** 平台的 AudioContext 构造器（含老 Safari 的 webkit 前缀名）；没有即不支持 Web Audio。 */
  ctor(): (new () => AudioContextLike) | undefined;
  now(): number;
}

export interface AudioEngine {
  /** 必须在用户手势内调用：后台播放提示音需要已解锁的 AudioContext。 */
  unlock(): void;
  /** 自播节流门：同一窗口内只放行一次，防通知风暴叠播。 */
  gate(): boolean;
  playTone(tone: string | undefined): void;
  /** 试听：显式解锁 + 绕过统一节流（用户手势内直接试听不受限制）。 */
  playPreview(tone: string | undefined): void;
  facts(): AudioFacts;
}

interface AudioContextWithFacts extends AudioContextLike {
  state: string;
  /** 是否跑到过 running；生命周期与上下文实例严格相同。 */
  __dshRan?: boolean;
  /** resume() 是否被拒绝。 */
  __dshResumeRejected?: boolean;
}

export function createAudioEngine(ports: AudioEnginePorts): AudioEngine {
  let ctx: AudioContextWithFacts | null = null;
  let lastPlayAt = 0;

  function ensureContext(): AudioContextWithFacts | null {
    if (ctx !== null) return ctx;
    const Ctor = ports.ctor();
    if (Ctor === undefined) return null;
    ctx = new Ctor() as AudioContextWithFacts;
    return ctx;
  }

  function unlock(): void {
    try {
      const audio = ensureContext();
      if (audio === null) return;
      // 两个事实记在上下文实例上而不是模块里：它们的生命周期与那个上下文严格相同，
      // 单独开变量会让重建上下文后旧标记残留（自检面于是谎报「已解锁」）。
      if (audio.state === "suspended") {
        const resumed = audio.resume();
        if (resumed && typeof resumed.then === "function") {
          resumed.then(
            () => {
              audio.__dshRan = true;
            },
            () => {
              audio.__dshResumeRejected = true;
            },
          );
        }
      }
      if (audio.state === "running") audio.__dshRan = true;
      // 播一个空 buffer：这是让上下文真正进入 running 的手势内仪式
      const buffer = audio.createBuffer(1, 1, 22050);
      const source = audio.createBufferSource();
      source.buffer = buffer;
      source.connect(audio.destination);
      source.start(0);
    } catch {
      // 音频不可用不阻塞通知
    }
  }

  function gate(): boolean {
    const now = ports.now();
    if (now - lastPlayAt < PLAY_THROTTLE_MS) return false;
    lastPlayAt = now;
    return true;
  }

  function playTone(tone: string | undefined): void {
    const audio = ctx;
    if (audio === null || audio.state !== "running") return;
    try {
      const start = audio.currentTime;
      const spec =
        tone !== undefined && Object.hasOwn(TONES, tone) ? TONES[tone] : TONES[FOLLOW_SYSTEM_TONE];
      for (const note of spec.notes) {
        const osc = audio.createOscillator();
        const gain = audio.createGain();
        osc.type = note.type || "sine";
        osc.frequency.value = note.freq;
        gain.gain.setValueAtTime(0.0001, start + note.at);
        gain.gain.exponentialRampToValueAtTime(0.18, start + note.at + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + note.at + note.dur);
        osc.connect(gain);
        gain.connect(audio.destination);
        osc.start(start + note.at);
        osc.stop(start + note.at + note.dur + 0.02);
      }
    } catch {
      // 播放失败忽略
    }
  }

  function playPreview(tone: string | undefined): void {
    unlock();
    playTone(tone);
  }

  function facts(): AudioFacts {
    const supported = ports.ctor() !== undefined;
    if (ctx === null) {
      return { supported, state: null, hasEverRun: false, resumeRejected: false };
    }
    return {
      supported,
      state: ctx.state as AudioFacts["state"],
      hasEverRun: ctx.__dshRan === true,
      resumeRejected: ctx.__dshResumeRejected === true,
    };
  }

  return { unlock, gate, playTone, playPreview, facts };
}

/**
 * dsh-notifier 客户端 —— 页面内即时反馈（横幅 + 短提示）。
 *
 * 非安全上下文（局域网 http）下系统级通知不可用，本模块是唯一的降级提醒通道。
 *
 * 裁剪做成纯函数不是为了复用，而是为了**可判据**：旧实现在 querySelectorAll 的静态快照上写
 * `while (banners.length >= 3) banners[0].remove()`，而 Element.remove() 不改变那个数组的长度，
 * 条件恒真。页面可见 + 系统通知不可用时，第 4 条不同 kind 的通知会让主线程同步忙等、整页冻结。
 * trimBanners 按算好的条数从最旧端淘汰，天然有界。
 */

/** 同屏最多保留的横幅条数（追加一条后不超过它）。 */
export const BANNER_CAP = 3;

/** 横幅 / 短提示的自动消失时长（毫秒）。 */
const BANNER_TTL_MS = 8000;
const TOAST_TTL_MS = 3000;

/** 可移除节点：本模块只用到 remove，测试因此不必造真实 DOM。 */
export interface Removable {
  remove(): void;
}

/** 追加一条之前需要淘汰的条数；0 表示还有空位。 */
export function bannerTrimCount(existing: number, cap: number): number {
  return Math.max(0, existing - cap + 1);
}

/** 从最旧端淘汰，使追加一条后总数不超过 cap。 */
export function trimBanners(banners: readonly Removable[], cap: number): void {
  for (const node of banners.slice(0, bannerTrimCount(banners.length, cap))) node.remove();
}

/** 本模块的 DOM 构造助手：只声明真正会写的属性——宽泛签名会让拼错的属性名不再报错。 */
interface ElAttrs {
  class?: string;
  text?: string;
  dataset?: Readonly<Record<string, string>>;
  style?: string;
}

function el(tag: string, attrs: ElAttrs, children?: readonly Node[]): HTMLElement {
  const node = document.createElement(tag);
  if (attrs.class !== undefined) node.className = attrs.class;
  if (attrs.text !== undefined) node.textContent = attrs.text;
  if (attrs.dataset !== undefined) Object.assign(node.dataset, attrs.dataset);
  if (attrs.style !== undefined) node.style.cssText = attrs.style;
  if (children !== undefined) {
    for (const child of children) node.appendChild(child);
  }
  return node;
}

/** 页面内横幅（点击聚焦，自动消失，最多 BANNER_CAP 条）。
 *  kind 由帧携带、可含任意字符，因此按 dataset 比对而不拼 CSS 选择器——拼选择器遇引号/反斜杠
 *  会抛错，而抛错会让整帧静默丢弃。 */
export function showBanner(kind: string, title: string, message: string): void {
  const kindKey = String(kind);
  const existing = Array.prototype.slice.call(
    document.querySelectorAll(".dn-banner"),
  ) as HTMLElement[];
  const survivors: HTMLElement[] = [];
  for (const node of existing) {
    if (node.dataset.kind === kindKey) node.remove();
    else survivors.push(node);
  }
  trimBanners(survivors, BANNER_CAP);
  const banner = el("div", { class: "dn-banner", dataset: { kind: kindKey } });
  banner.addEventListener("click", () => {
    window.focus();
    banner.remove();
  });
  banner.appendChild(
    el("div", { style: "display:flex;align-items:center;gap:6px" }, [
      el("span", { text: "🔔" }),
      el("span", { text: title, style: "font-weight:600" }),
    ]),
  );
  banner.appendChild(
    el("div", {
      text: message,
      style: "margin-top:4px;font-size:12px;line-height:1.5;white-space:pre-line",
    }),
  );
  document.body.appendChild(banner);
  setTimeout(() => {
    banner.remove();
  }, BANNER_TTL_MS);
}

/** 页面内短提示（操作反馈）。 */
export function toast(message: string): void {
  const node = el("div", { class: "dn-toast", text: message });
  document.body.appendChild(node);
  setTimeout(() => {
    node.remove();
  }, TOAST_TTL_MS);
}

/**
 * dsh-notifier 客户端 —— 多标签主从租约。
 *
 * 同一个 URL 在同一个浏览器里开多个标签时，只有持租约的那个标签提醒，其余静默；租约过期即被
 * 抢占。storage 与时钟都从参数进来，判定因此可以在 node 里被穷举——这是原先拿不到的
 * （它直接读写 localStorage 与 Date.now）。
 *
 * 两条行为是刻意的，别在重写时「修正」：
 * 1. 任何异常（storage 不可用、JSON 损坏）一律放行（返回 true）——宁可在多标签下重复提醒，
 *    也不要在隐私模式/受限环境里彻底不提醒；
 * 2. 租约身份是**跨实例共享**的量（同一页面重新挂载仍是同一个标签），所以 tabId 由调用方
 *    持有并复用，而不是每次装配新生成一个。
 */

/** storage 键与租约时长。 */
export const MASTER_KEY = "dsh-notifier:master";
export const MASTER_LEASE_MS = 15000;

/** 租约判定要用到的两类外部事实。 */
export interface LeasePorts {
  now(): number;
  read(): string | null;
  write(value: string): void;
}

function parseLease(raw: string | null): Record<string, unknown> | null {
  // 假值（含空串）一律当「没有租约」：这不是防御性写法而是既有语义——storage 里出现空串时
  // 旧实现直接抢占并写入，若改成 JSON.parse("") 会走异常分支返回 true 但**不写**租约，
  // 于是后续每个标签都各自放行（多标签重复提醒）。
  if (!raw) return null;
  const value: unknown = JSON.parse(raw);
  if (typeof value !== "object" || value === null || Array.isArray(value)) return null;
  const lease = value as Record<string, unknown>;
  if (typeof lease.id !== "string" || typeof lease.ts !== "number") return null;
  return lease;
}

/**
 * 取租约：持租约且未过期 → 续租并返回 true；属于别的标签且未过期 → false；无主/已过期 → 抢占。
 */
export function claimMaster(tabId: string, ports: LeasePorts): boolean {
  try {
    const lease = parseLease(ports.read());
    const now = ports.now();
    const ts = lease === null ? undefined : lease.ts;
    if (lease !== null && typeof ts === "number" && now - ts < MASTER_LEASE_MS) {
      if (lease.id === tabId) {
        // 保留解析出的其它键：租约节点将来加字段时，续租不该把它们抹掉
        ports.write(JSON.stringify(Object.assign({}, lease, { ts: now })));
        return true;
      }
      return false;
    }
    ports.write(JSON.stringify({ id: tabId, ts: now }));
    return true;
  } catch {
    return true;
  }
}

/**
 * dsh-notifier 客户端 —— 通知帧的展示策略（纯判定）。
 *
 * 「这一帧要不要提醒、走哪条通道、要不要页内自播」原先散在 showNotification /
 * handleNotifyFrame 两个函数里，与 Notification 构造、DOM 横幅、音频播放交织在一起，
 * 因此每条分支都没有判据。这里把判定提成纯函数：输入是帧与页面现状，输出是通道与声音策略，
 * 副作用留给调用方。
 *
 * 三条语义容易在重写中被「顺手简化」掉，故此处逐条保留：
 * 1. 缺 sound 字段的旧帧按「跟随系统默认」处理（0.2.3 的服务端不发这个字段）；
 * 2. playOnly + mode:"system" 归一为自播——无弹窗实体时 OS 不会发声，不归一就是「0 弹 0 播纯静默」；
 * 3. playOnly 不受页面可见性约束（纯声音提醒，不打扰界面）。
 */

/** 服务端下发的声音策略：静音 / 跟随系统默认（交给 OS）/ 页内自播（系统弹窗 silent 防双响）。 */
export interface SoundPolicy {
  selfPlay: boolean;
  silent: boolean;
  tone: string | undefined;
}

/** 一帧提醒的落点。 */
export type DisplayChannel = "notification" | "banner" | "title" | "none";

/**
 * 帧里的声音策略（帧级权威，不回查配置）。
 *
 * @param sound 帧的 sound 字段；缺失/非对象一律按 `{mode:"system"}`。
 * @param playOnly 只响不弹：不弹实体、仅按需自播。
 */
export function soundPolicyOf(sound: unknown, playOnly: boolean): SoundPolicy {
  const frame =
    typeof sound === "object" && sound !== null
      ? (sound as { mode?: unknown; tone?: unknown })
      : { mode: "system" };
  // 弹窗实体与 OS 发声二选一：selfplay 必须把自己标成 silent，否则与页内自播叠成双响
  const selfPlay = frame.mode === "selfplay";
  const baseSilent = frame.mode === "silent" || selfPlay;
  const tone = typeof frame.tone === "string" ? frame.tone : undefined;
  if (playOnly && frame.mode === "system") {
    return { selfPlay: true, silent: true, tone };
  }
  return { selfPlay, silent: baseSilent, tone };
}

/**
 * 降级通道：不弹系统通知时用横幅还是标题闪烁。页面可见时用横幅（用户看得见），
 * 隐藏时改标题（横幅在看不见的页面上没有意义）。playOnly 两者都不用。
 */
export function fallbackChannelOf(playOnly: boolean, visibility: string): DisplayChannel {
  if (playOnly) return "none";
  return visibility !== "hidden" ? "banner" : "title";
}

/** 是否走系统级通知：playOnly 不弹实体；不可用时走降级通道。 */
export function displayChannelOf(input: {
  playOnly: boolean;
  notificationUsable: boolean;
  visibility: string;
}): DisplayChannel {
  if (!input.playOnly && input.notificationUsable) return "notification";
  return fallbackChannelOf(input.playOnly, input.visibility);
}

/**
 * 帧要不要处理。
 *
 * 测试通知无条件处理（验证链路就是它的目的，与可见性、开关无关）；其余帧在页面可见时默认
 * 不提醒，除非帧自己说「可见时也弹」（whenVisible）——判定归宿主出口，页面不回查配置。
 * playOnly 例外：它不打扰界面，纯声音提醒，因此不受可见性约束。
 */
export function frameAccepted(input: {
  kind: unknown;
  whenVisible: unknown;
  playOnly: unknown;
  visibility: string;
}): boolean {
  if (input.kind === "test") return true;
  if (input.visibility !== "hidden" && input.whenVisible !== true) {
    return input.playOnly === true;
  }
  return true;
}

/**
 * dsh-notifier 客户端 —— 已弹出的系统通知登记。
 *
 * 保留最近 NOTIFICATION_KEEP 条、超出即关最旧的；卸载时只关**自己登记的**那些。通知是瞬时
 * 提醒，插件卸载后没有可归属的宿主；但热更或重复 apply 时旧实例的 disposer 仍会执行，全关会
 * 连带关掉新实例正在显示的弹窗（跨实例串味），故按归属者分账。
 *
 * **上限仍是页面级的**：NOTIFICATION_KEEP 说的是「整个页面同时留几条弹窗」，超限淘汰永远挤掉
 * 页面上最旧的那条，不按归属分账——按实例各算一份会让「最多 5 条」变成「每实例 5 条」。
 *
 * 用模块级 const 容器承载：同一页面只有一组弹出通知。
 */

/** 同时保留的弹出通知条数。 */
export const NOTIFICATION_KEEP = 5;

interface ShownNotification {
  notification: { close(): void };
  owner: object;
}

const shown: ShownNotification[] = [];

/** 登记一条已弹出的通知，超出页面上限即关掉最旧的那条（不分归属）。 */
export function trackNotification(notification: { close(): void }, owner: object): void {
  shown.push({ notification, owner });
  if (shown.length > NOTIFICATION_KEEP) shown.shift()?.notification.close();
}

/**
 * 关闭并摘除 owner 自己登记的通知（卸载路径）。别的实例登记的弹窗不动，关闭失败的单个通知也
 * 不影响其余——但登记项一律摘除：注册表不再持有即将卸载的实例的资源。
 */
export function closeNotificationsOf(owner: object): void {
  const owned: { close(): void }[] = [];
  for (let i = shown.length - 1; i >= 0; i -= 1) {
    const entry = shown[i]!;
    if (entry.owner === owner) {
      owned.unshift(entry.notification);
      shown.splice(i, 1);
    }
  }
  for (const notification of owned) {
    try {
      notification.close();
    } catch {
      // 关闭失败不影响卸载
    }
  }
}

/**
 * dsh-notifier 客户端 —— SSE 通知流会话。
 *
 * 连接、看门狗、断线重连与 seq 去重原先直接 new EventSource 并用真实的 setTimeout/Date.now，
 * 于是「重连是否带上 since」「重复帧有没有被丢」「半开连接能不能被发现」全都测不到——而这三条
 * 正是断线窗口里丢通知的三个成因。时间与连接都从端口进来之后，它们可以用假时钟与假
 * EventSource 精确驱动。
 *
 * 三条语义是刻意的，别在重写时简化：
 * 1. 重连必须带 since：EventSource 自动重连不携带 query，不带就等于把断线期间的事件丢掉；
 * 2. 只有**解析成功**的帧才刷新 lastActivity——畸形帧不该让半开检测失效；
 * 3. 重连有最小间隔：onerror 与看门狗会互相触发，不设间隔就是重连风暴。
 */

/** 看门狗窗口：这么久没有任何帧（notify 或心跳 ping）就主动重建。 */
export const WATCHDOG_MS = 60000;

/** 看门狗检查的起始延迟：比窗口长 5 秒，避免恰好在边界上误判。 */
const WATCHDOG_ARM_MS = WATCHDOG_MS + 5000;

/** 重连最小间隔（毫秒）。 */
const RECONNECT_MIN_GAP_MS = 5000;

/** 通知流连接的最小可判别面。 */
export interface EventSourceLike {
  onmessage: ((event: { data: string }) => void) | null;
  onerror: (() => void) | null;
  close(): void;
}

export interface SessionPorts {
  /** 通知流地址（不含 since 查询参数）。 */
  url: string;
  createSource(url: string): EventSourceLike;
  now(): number;
  setTimer(fn: () => void, ms: number): number;
  clearTimer(handle: number): void;
  /** 非致命问题的留痕出口（解析失败、关闭失败、EventSource 不可用）。 */
  warn(message: string, cause: unknown): void;
}

export interface NotifySession {
  close(): void;
  reconnect(): void;
}

export function startNotifySession(
  ports: SessionPorts,
  onFrame: (frame: Record<string, unknown>) => void,
): NotifySession {
  let source: EventSourceLike | null = null;
  let lastActivity = 0;
  // lastSeq 既是去重水位又是 since 的起点：两者必须同源，否则要么重复提醒、要么漏帧
  let lastSeq = 0;
  let watchdog: number | null = null;
  let lastReconnectAt = 0;

  function armWatchdog(): void {
    if (watchdog !== null) ports.clearTimer(watchdog);
    watchdog = ports.setTimer(() => {
      if (ports.now() - lastActivity > WATCHDOG_MS) forceReconnect();
      else armWatchdog();
    }, WATCHDOG_ARM_MS);
  }

  function forceReconnect(): void {
    const now = ports.now();
    if (now - lastReconnectAt < RECONNECT_MIN_GAP_MS) return;
    lastReconnectAt = now;
    closeSource();
    connect();
  }

  function closeSource(): void {
    if (source === null) return;
    try {
      source.close();
    } catch (error) {
      ports.warn("关闭旧 SSE 连接失败", error);
    }
    source = null;
  }

  function connect(): void {
    closeSource();
    try {
      const url = ports.url + (lastSeq > 0 ? "?since=" + lastSeq : "");
      const next = ports.createSource(url);
      source = next;
      lastActivity = ports.now();
      next.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data) as Record<string, unknown>;
          lastActivity = ports.now();
          if (data.type === "ping") return;
          if (data.type === "notify") {
            if (typeof data.seq === "number") {
              if (lastSeq > 0 && data.seq <= lastSeq) return;
              lastSeq = data.seq;
            }
            onFrame(data);
          }
        } catch (error) {
          ports.warn("帧解析失败", error);
        }
      };
      next.onerror = () => {
        // 主动重建（带 since 补拉）：EventSource 自动重连不携带 query，无法回放
        forceReconnect();
      };
      armWatchdog();
    } catch (error) {
      ports.warn("EventSource 不可用", error);
    }
  }

  connect();
  return {
    close(): void {
      if (watchdog !== null) ports.clearTimer(watchdog);
      closeSource();
    },
    reconnect: forceReconnect,
  };
}

/**
 * dsh-notifier 客户端 —— 标题闪烁（页面隐藏时的降级提醒）。
 *
 * document.title 是页面级共享事实（一个页面只有一份标题），所以恢复缓存用 const 容器承载，
 * 而不是每个实例各存一份。
 *
 * 恢复有两条路径：回前台、卸载。少任何一条都会让标题永久卡在「🔔 …」——「隐藏时收到通知、
 * 随后插件被卸载」正是那条容易漏掉的路径，所以 restore 必须幂等且可重复调用。
 *
 * 归属判定是必须的：热更或重复 apply 时旧实例的 disposer 仍会执行，若它无条件 restore，
 * 就会摘掉新实例刚点亮的闪烁——「隐藏页收到通知」的提示就此消失，而这条降级通道是通知被
 * 静音/无权限时唯一的可见提醒。故闪烁记下归属者，只有归属者自己的 restore 才还原。
 */
export interface TitlePorts {
  get(): string;
  set(value: string): void;
}

export interface TitleFlasher {
  flash(title: string, owner: object): void;
  restore(owner: object): void;
}

export function createTitleFlasher(ports: TitlePorts): TitleFlasher {
  let saved: string | null = null;
  let owner: object | null = null;
  return {
    flash(title: string, caller: object): void {
      // 恢复缓存只记第一次的原文（连续闪烁时被覆盖的应该是同一份原始标题）；归属者则跟随最近
      // 一次闪烁——后装/最近的实例才是当前闪烁的主人，否则旧实例的 disposer 一 restore 就把它摘了。
      if (saved === null) saved = ports.get();
      owner = caller;
      ports.set("🔔 " + String(title).slice(0, 40));
    },
    restore(caller: object): void {
      if (saved === null || owner !== caller) return;
      ports.set(saved);
      saved = null;
      owner = null;
    },
  };
}

/** 本页的标题闪烁器（跨实例共享同一份恢复缓存与归属者）。 */
export const titleFlasher = createTitleFlasher({
  get: () => document.title,
  set: (value) => {
    document.title = value;
  },
});

