/**
 * dsh-notifier 客户端 —— 设置草稿的纯逻辑（差异 / 域过滤 / 字段合并 / 数值钳制）。
 *
 * 抽出来的理由不是分层好看，而是**可判据**：这几个函数决定「保存什么」——提交哪些键、
 * 什么时候整组带走 channels、清空输入算删键还是写空串。它们原先住在 index.tsx 内，而那个
 * 文件 import 了 react 与 style.css，node 无法导入，于是只能挂在公共 apply 上或对源码做正则
 * 来测，实际结果是一条判据都没有。零依赖的独立模块让它们第一次可以被直测。
 *
 * 跨端契约提醒：channels 的空串形态同时被服务端读面 normalize 与服务端写面校验解释，
 * 动这里的剥除/删键语义等于动服务端行为，必须两端一起看。
 */

/**
 * 基线 diff：返回 settings 相对 baseLine 中**值不同**的键集合（增量 patch，只提交变更键——
 * 防组合层 base 被默认值回写覆盖）。深比较走 stableEqual（键序无关，见下）；比较双方先过
 * 同一比较规范形（normalizeChannelForCompare，双侧——#912 以前只剥 cur 侧，base 侧残留
 * 空串即恒脏）。settings 中不存在于 baseLine 的新增键（diff 语义下的新增）与值不同的
 * 既有键都会被提交；baseLine 中已删除的键不提交删除（增量 merge patch 无删除语义）。
 *
 * 提交形态与比较形态是两回事：payload 里放的是 strip 形态（只剥空串，auth/preset/timeout
 * 与 levels 等原样提交——服务端写面校验看到的是用户真值，缺 auth 照常 400）；比较时才用
 * 规范形（缺键补服务端默认值）。两者分离，比较再对称也不会把一次合法提交洗成非法。
 *
 * @param settings 当前 UI 编辑态（snapshotBaseline 起点，见下）。
 * @param baseLine 加载基线（snapshotBaseline 快照，见下）。
 */
export function diffSettingsPayload(
  settings: Record<string, unknown>,
  baseLine: Record<string, unknown> | null,
): Record<string, unknown> {
  const payload: Record<string, unknown> = {};
  if (baseLine === null) return payload;
  for (const key in settings) {
    if (!Object.prototype.hasOwnProperty.call(settings, key)) continue;
    const cur = settings[key];
    const base = baseLine[key];
    // channels 整组提交前对实例做空串可选字段剥除——存量配置（0.2.2 保存失败前/手改 yaml/
    // 旧版本）可能残留 token:"" 等空串形态，UI 编辑任一字段都会触发整组提交把残留一起带走
    // → 400 死锁。剥除与读面 normalize（空串按未配置剥除）同语义，纯读不改草稿，用户后续
    // 输入仍经 assignChannelFields 正常写。
    const value = key === "channels" && Array.isArray(cur) ? cur.map(stripChannelEmpties) : cur;
    const same = stableEqual(canonicalForCompare(key, cur), canonicalForCompare(key, base));
    if (!same) payload[key] = value;
  }
  return payload;
}

/** 空串即「未配置」的可选 string 字段清单（bark 与 webhook 实例的**并集**）。
 *  `url` 在这里是因为 bark 的 url 是可选的自定义端点覆写；对 webhook 而言 url 是必填，但那条路
 *  走不到剥除——UI 写回时 assignChannelFields 已把空串删键，接着服务端 validateWebhookChannel
 *  以「缺少 url」400 拦下（而不是静默写进一个打不通的地址）。
 *  真正不在清单内的是 id/type/baseUrl/deviceKey/auth：为空时原样提交、由服务端写面校验拦
 *  （必填不允许空，语义正确）；非 string 值（number/boolean/levels 对象）不触碰。 */
const CHANNEL_OPTIONAL_STRING_KEYS: readonly string[] = [
  "name",
  "token",
  "username",
  "password",
  "headerName",
  "headerValue",
  "template",
  "sound",
  "group",
  "icon",
  "url",
];

/** 单个频道实例的空串可选字段剥除：浅拷贝后删除值为空串的可选字段。只处理 string 值，
 *  number/boolean/对象字段不触碰；非对象输入原样返回（防御数组/null）。 */
export function stripChannelEmpties(ch: unknown): unknown {
  if (typeof ch !== "object" || ch === null || Array.isArray(ch)) return ch;
  const out = Object.assign({}, ch as Record<string, unknown>);
  for (const key of CHANNEL_OPTIONAL_STRING_KEYS) {
    if (typeof out[key] === "string" && (out[key] as string).length === 0) delete out[key];
  }
  return out;
}

/** 单键的比较规范形：channels 逐项过 normalizeChannelForCompare，其余键原样。 */
function canonicalForCompare(key: string, value: unknown): unknown {
  if (key === "channels" && Array.isArray(value)) return value.map(normalizeChannelForCompare);
  return value;
}

/**
 * 稳定序列化（与服务端 config/impl/service 的 stableJson 同语义，#912 比较键序无关的参照）：
 * 对象递归按键排序，数组保持原序（数组顺序是内容的一部分——频道顺序变了就是变了）。
 * undefined 按 JSON 语义消化：对象里的 undefined 值键直接丢弃（与 JSON.stringify 一致，
 * 基线缺键与草稿显式写 undefined 因此同形）；数组里的 undefined 记 null（同 JSON）；
 * 顶层 undefined（基线缺键逐键读出的形态）给一个显式规范形，保证可比。
 */
export function stableJsonValue(value: unknown): string {
  if (value === undefined) return "undefined";
  if (Array.isArray(value)) {
    return `[${value.map((item) => (item === undefined ? "null" : stableJsonValue(item))).join(",")}]`;
  }
  if (typeof value === "object" && value !== null) {
    const record = value as Record<string, unknown>;
    const fields = Object.keys(record)
      .filter((field) => record[field] !== undefined)
      .sort()
      .map((field) => `${JSON.stringify(field)}:${stableJsonValue(record[field])}`);
    return `{${fields.join(",")}}`;
  }
  return JSON.stringify(value) ?? "undefined";
}

/**
 * 键序无关的深相等：比较双方先过同一规范形。
 *
 * 以前的口径是“键序不同即视为已变”；#912 改为无关——Object.assign 浅拷贝与合并处的键序
 * 取决于写路径（load/discard/rebase/putAndCommit 各不相同），与用户是否改过东西无关，
 * 敏感即误报（首屏恒脏的次要成因）。
 */
export function stableEqual(a: unknown, b: unknown): boolean {
  return stableJsonValue(a) === stableJsonValue(b);
}

/**
 * 频道实例的比较规范形：与服务端读面 normalize 同语义的收敛（纯读，返回浅拷贝）。
 *
 * - 可选 string 空串剥除：复用 stripChannelEmpties 的清单，不扩大——id/type/baseUrl 与
 *   deviceKey/auth 的空串仍原样保留，由服务端写面校验拦（必填不允许空）；非 string 不动；
 * - 缺键按类型补服务端默认值（只补缺席，已有的值原样保留——值域对错是写面的事，比较不替它断案）：
 *   bark 补 levels 空对象与 timeoutMs 0，webhook 补 headers 空对象、timeoutSec 0、preset custom、
 *   auth none，内置（browser/system）与未知类型不补。这只是比较用的补齐，payload 里仍是草稿原值
 *   （auth 缺席的提交照常被服务端 400——比较对称化没有把校验洗掉）；
 * - 掩码与其它非空值一律保留：掩码相等即未改，携带新值即脏（提交后由服务端按 id 还原）。
 *
 * 为什么按类型补而不是全量补：全量补会把 webhook 的 headers 空对象塞进 bark（或反向），
 * 提交时 validateExtras 以“只能是字符串或数字”400 拒收——比较对称不能污染提交形态。
 * 为什么是补齐而不是删空（例如删掉 levels 空对象或 timeout 0）：删空会把用户删掉最后一个
 * levels 映射洗成无变化（相对空基线恒等），那次删除就永远存不下去；补齐只统一缺席与
 * 默认值两种写法，真删除（非空变空）两侧仍不等。
 */
export function normalizeChannelForCompare(ch: unknown): unknown {
  const stripped = stripChannelEmpties(ch);
  if (typeof stripped !== "object" || stripped === null || Array.isArray(stripped)) return stripped;
  const out = stripped as Record<string, unknown>;
  if (out.type === "bark") {
    if (out.levels === undefined) out.levels = {};
    if (out.timeoutMs === undefined) out.timeoutMs = 0;
  } else if (out.type === "webhook") {
    if (out.headers === undefined) out.headers = {};
    if (out.timeoutSec === undefined) out.timeoutSec = 0;
    if (out.preset === undefined) out.preset = "custom";
    if (out.auth === undefined) out.auth = "none";
  }
  return out;
}

/**
 * 设置整体的比较规范形：channels 逐项过 normalizeChannelForCompare，其余键原样（浅拷贝）。
 *
 * 只收敛 channels：UI 写回删键（assignChannelFields 与 chLevelsSet）与服务端读面兜底的形态
 * 分叉只发生在这里；quietHours 与 kindRoutes 等两侧恒同形，不需要第二份实现。
 */
export function canonicalSettingsForCompare(
  settings: Record<string, unknown>,
): Record<string, unknown> {
  const out = Object.assign({}, settings);
  if (Array.isArray(out.channels)) out.channels = out.channels.map(normalizeChannelForCompare);
  return out;
}

/**
 * 基线快照：服务端 effective 写进 baselineRef 之前先过比较规范形。
 *
 * load 与 discard 与 quiet（applyLatestQuiet）与冲突覆盖（resolveConflictOverwrite）四路径
 * 统一走这里——基线存的是收敛后的形态，重拉与放弃即与草稿同形，不复脏。草稿侧同样用它
 * （渲染等价：输入框里 undefined 与空串同显空，levels 缺席与空对象同由调用点兜住，auth 缺席
 * 回落 none）；提交 payload 仍带齐 auth 与 preset 与 timeout（补齐的值服务端本来就会兜底，
 * wire 语义不变——chAdd 预置的 auth none 与 timeoutSec 10 照常提交）。
 */
export function snapshotBaseline(effective: Record<string, unknown>): Record<string, unknown> {
  return canonicalSettingsForCompare(effective);
}

/**
 * 409 冲突「保留我的修改并覆盖」的 rebase：以服务端最新 effective 为基底，把本地变更键的值
 * 覆盖上去（键级 last-write-wins，与 JSON Merge Patch / Firebase per-key merge 同语义）——
 * 本地变更键集合由调用方在用户触发「覆盖」动作时实时重算（非 409 时刻快照，横幅期间的新编辑
 * 不丢）。顶层浅拷贝即可（settings 不可变更新模式，patch 不原位改对象）。
 *
 * @param localChanges 本地相对旧基线的变更键集合（域/全量均适用）。
 * @param remoteEffective 服务端最新 effective（GET /config 拉取）。
 */
export function rebaseSettings(
  localChanges: Record<string, unknown>,
  remoteEffective: Record<string, unknown>,
): Record<string, unknown> {
  return Object.assign({}, remoteEffective, localChanges);
}

/**
 * 按保存入口从全量 diff 中取子集（域保存）：
 * - entry "all"：原样返回（foot 全量保存）；
 * - entry "channels"：仅保留 channels 键（频道域保存——事件/参数半成品草稿不随频道域保存
 *   提交）；该键不存在时返回空对象；
 * - 未知入口：返回空对象（保守不提交——fail-closed，写错枚举值只会少提交，不会多提交）。
 */
export function domainPayload(
  diff: Record<string, unknown>,
  entry: string,
): Record<string, unknown> {
  if (entry === "all") return diff;
  if (entry === "channels") {
    if (!Object.prototype.hasOwnProperty.call(diff, "channels")) return {};
    return { channels: diff.channels };
  }
  return {};
}

/**
 * 频道实例字段合并：part 中**空串/undefined 值从 target 删除该键**，其余浅覆盖。
 *
 * 空串在服务端写面校验中是「非法值」而非「未配置」——token/username/password/headerValue
 * 要求非空、headerName 过头名正则；读面 normalize 却把空串剥除（等价未配置）。若把清空输入
 * 回写成 "" 提交，实例会带着空串残留被整组 400（「填了又删空」死锁的必现根因之一）——空串
 * 删键后提交面与读面同语义（键不存在 = 未配置）。undefined 一并删键：数字/下拉清空走的是
 * 同一条路（清空 badge/level 传的就是 undefined），而 Object.assign 会把 undefined 保留成
 * 「有这个键但值为 undefined」，JSON 序列化后与删键等价、但草稿对象本身多一个键，
 * 「键在不在」正是 levels/badge 这些字段的值域判据。
 */
export function assignChannelFields(
  target: Record<string, unknown>,
  part: Record<string, unknown>,
): Record<string, unknown> {
  const out = Object.assign({}, target);
  for (const key of Object.keys(part)) {
    const value = part[key];
    if (value === "" || value === undefined) delete out[key];
    else out[key] = value;
  }
  return out;
}

/**
 * dsh-notifier 客户端 —— 凭据掩码字段的编辑语义。
 *
 * 服务端把已配置的凭据掩码后送进设置视图（config/impl/redact），写回时**只把恰好等于掩码的
 * 值**判为「未修改」并按 id 还原。因此掩码不是可以出现在输入框里的字面量：它一旦被用户改写
 * （在圆点后追加一个字符），提交值就不再等于掩码，服务端会把它当成新凭据落盘——真 key 丢失、
 * 该通道此后每次投递必败，而界面显示「已保存」。
 *
 * 本模块把这条语义收成一个可判据的纯函数：未编辑时渲染空值（占位符给出「已配置」提示），
 * 只有用户真的输入过才把字段写进草稿；未编辑的字段保持服务端掩码原样提交，由服务端还原。
 */

/** 已配置凭据在输入框里的占位提示（与后缀同一形态，不承载真实值）。 */
export const CREDENTIAL_MASK_PLACEHOLDER = "••••••••";

/** 服务端视图里该字段是否代表「已配置」：空串与缺失都是未配置（读面把空串剥掉了）。 */
export function isCredentialConfigured(raw: unknown): boolean {
  return typeof raw === "string" && raw !== "";
}

/** 凭据字段的瞬态键（<频道 id>:<字段>）：显隐与「已被用户编辑」两个瞬态集合共用同一形态。 */
export function credentialFieldKey(channelId: string, field: string): string {
  return `${channelId}:${field}`;
}

/** 输入框的渲染值：未编辑时为空——掩码不可作为可编辑字面量出现。 */
export function maskedFieldValue(raw: unknown, edited: boolean): string {
  if (!edited) return "";
  return typeof raw === "string" ? raw : "";
}

/** 一个凭据输入框要渲染的三件事：值、占位提示、是否已配置（后者驱动调用方的提示文案）。 */
export interface CredentialFieldView {
  value: string;
  placeholder: string;
  configured: boolean;
}

/** 凭据输入框的唯一投影：两张卡片（bark / webhook）都只消费它，掩码语义不出现第二份。 */
export function credentialFieldView(
  raw: unknown,
  edited: boolean,
  fallbackPlaceholder: string,
): CredentialFieldView {
  const configured = isCredentialConfigured(raw);
  return {
    value: maskedFieldValue(raw, edited),
    placeholder: configured ? CREDENTIAL_MASK_PLACEHOLDER : fallbackPlaceholder,
    configured,
  };
}

/**
 * 设置卡投递摘要 / 脏状态纯决策函数（M2：原内联在 SettingsCard 闭包里，
 * 逻辑改坏时源码扫描型测试全绿——抽到此处配可执行断言）。
 *
 * 零依赖（t 由调用方注入），不 import server 面，client-unit node 直跑。
 */
import type { Translate } from "../../locale.ts";

/**
 * 投递摘要文案：默认收成一行。
 * - 点亮且启用的频道按名点名（真实投递面 = 启用 ∩ 点亮，停用频道不点名）；
 * - 无点名但已自定义 → 自定义态（N = 快照内现存候选数，stale 残留另以独立
 *   chip 呈现，不重复计入 N）；
 * - 跟随默认 → 默认态。
 */
export function routeSummaryText(
  litLabels: string[],
  isCustom: boolean,
  liveCount: number,
  t: Translate,
): string {
  if (litLabels.length > 0) {
    const more = litLabels.length > 2 ? litLabels.length - 2 : 0;
    return litLabels.slice(0, 2).join(" · ") + (more > 0 ? " · +" + String(more) : "");
  }
  if (isCustom) return t("routeCustomState", { n: liveCount });
  return t("routeDefaultState");
}

/**
 * 底栏脏文案：按域表述。channels 域负载是顶层单键（{} 或 {channels}），
 * 故只判「域是否脏」不数 N；事件域脏数 = 全量顶层键数 − 频道域（0/1）。
 * 无脏时返回 null（调用方不渲染）。
 */
export function dirtyStatusText(
  dirtyCount: number,
  channelsDirty: boolean,
  otherDirtyCount: number,
  t: Translate,
): string | null {
  if (dirtyCount <= 0) return null;
  if (channelsDirty && otherDirtyCount > 0) return t("dirtyDomains");
  if (channelsDirty) return t("dirtyChannels");
  return t("dirtySome", { n: dirtyCount });
}

/**
 * dsh-notifier 客户端 —— 保存串行 guard（同一时刻仅一个在途保存请求）。
 *
 * exhaustMap + trailing 语义：在途期间再点保存不丢弃意图——记 pending（含入口标识），由调用方
 * 在本轮在途结束（end）后按同一入口补发一次（补发是完整保存，是否仍有脏由调用方的 diff 空
 * 检查兜底，天然不循环）。
 *
 * 为什么 pending 记入口而不是布尔：有两个保存入口——foot 全量（"all"）与频道 tab 域保存
 * （"channels"），语义不同。在途期间被拒的入口必须原样补发：若「保存频道」被拒却补发全量，
 * 会把事件 tab 的半成品草稿一并提交。同一次在途多次点击不同入口时记最后一次意图
 * （end 只返回一个入口，天然不风暴）。
 */

export interface SaveGuard {
  /** 空闲则占用并返回 true；在途则记 pending=entry 并返回 false。 */
  tryBegin(entry: string): boolean;
  isBusy(): boolean;
  /** 释放占用；返回「在途期间最后一次被拒的入口」（调用方据此同入口补发一次），无则 null。 */
  end(): string | null;
}

/**
 * 必须与 tryBegin 成功一一配对（放 finally），任何路径都释放，防按钮永久卡死。
 */
export function createSaveGuard(): SaveGuard {
  let busy = false;
  let pending: string | null = null;
  return {
    tryBegin(entry: string): boolean {
      if (busy) {
        pending = entry;
        return false;
      }
      busy = true;
      return true;
    },
    isBusy(): boolean {
      return busy;
    },
    end(): string | null {
      busy = false;
      const last = pending;
      pending = null;
      return last;
    },
  };
}

/**
 * dsh-notifier 客户端 —— 测试投递的状态收敛轮询（纯逻辑，零 React 零 DOM，可直测）。
 *
 * 背景（#912 症状2次因）：POST /test 是 fire-and-forget，只承诺“已受理”；旧客户端只做一次
 * 即时 loadStatus，必抢在“能力探测秒级 + 子进程投递秒级 + 状态落盘 debounce 500ms”之前，
 * 真失败（failed）因此显示为“尚未投递”。本模块把“等终态”收成一个可判据的有限轮询。
 *
 * 收敛判据：以目标频道的条目出现/lastTs 推进为准（调用方在 POST 前记下 prevTs）。
 * - 有限轮：默认 8 轮 x 1500ms，预算约 12s，常见覆盖“能力探测（probe 3s 预算）+ 子进程投递
 *   （spawn 8s 超时）+ 落盘 debounce 500ms”。注意 GET /status 读的是内存镜像（即时），
 *   预算里的大头是投递本身，不是落盘。最坏不覆盖：webhook 投递 clamp 上限 60s、冷启动能力探测
 *   8s 与 system kill 8s 串行最坏超 12s——耗尽是 fail-safe（保留旧态 + 刷历史，不谎报），
 *   不是正确性缺陷（常量未链接服务端超时事实源，记债 #912-T3，见 issue 债清单）。
 * - 只读轮询：轮询只打 GET /status，绝不重发 POST /test——重发会撞上 system 出口 1 秒节流窗，
 *   第二次受理变成 throttled 的 skipped（无状态可写），等于用一次“没投递”去等“投递结论”。
 *   间隔取 1500ms（> 1000ms 节流窗）是双保险：即使用户在轮询期间又点了一次测试，两次投递
 *   的结论也不会在同一节流窗里互 alias。
 * - 失败保留旧态：单轮 fetch 抛错只记“这次没拿到”，继续下一轮；全部轮次都没拿到（map 为 null）
 *   时调用方必须保留旧 statusMap（不清空状态行——瞬时抖动不该丢已展示的终态）。耗尽仍未收敛
 *   时返回最后一份成功读到的表（可能为 null），由调用方决定展示（旧态 + 刷新历史）。
 *
 * skipped 可见性决策（二选一，#912 要求 PR 内定、不混写）：选“历史直达”，不改 skipped 值域。
 * - 弃“改值域”：把 skipped 写进 status（ok/failed/skipped 三值）要同步改类型守卫
 *   （stores normalizeEntry）、落盘形态、dispatch settle 的三处判据与理由字典，属于 GET /status
 *   契约变更，影响面大；而“没有投递”本来就没有“最后一次投递结论”，写进去的是伪结论。
 * - 取“历史直达”：skipped 的明细与原因本来就在通知历史里（dispatch 如实归档），状态行在无
 *   条目时若历史中有该频道的 skipped，就把原因与“详情见通知记录”摆出来（见 parts/status.tsx
 *   的 statusText history 形参）。值域保持 ok/failed 锁死，dispatch.test.ts 的锁死判据不动。
 *   已知代价：poll 只收敛 status 不看 history，skipped 主导的测试必等满 12s 耗尽才刷历史
 *   出解释（先排除 failed 的设计代价，最小实现下可接受；后续可做 history 早收敛优化，
 *   记债 #912-T4，见 issue 债清单）。
 */

/** 状态表读视图（GET /status channels 元素的渲染子集；只取判定用得上的字段）。 */
export interface StatusEntryView {
  lastTs?: unknown;
  lastStatus?: unknown;
  lastError?: unknown;
}

/** 状态表视图（键为频道 id，内置裸 type、实例 type:id，与服务端 channelIdOf 同源）。 */
export type StatusMapView = Record<string, StatusEntryView | undefined>;

/** 轮询入参：轮次与间隔可配（测试注入 sleep 钉住时间，不真等）。 */
export interface StatusPollOptions {
  /** 最大轮次（含首轮即时读）。缺省 TEST_STATUS_ATTEMPTS。 */
  attempts?: number;
  /** 轮间间隔毫秒（首轮前不睡）。缺省 TEST_STATUS_INTERVAL_MS。 */
  intervalMs?: number;
  /** 睡眠端口（缺省走 setTimeout；测试注入假件）。 */
  sleep?: (ms: number) => Promise<void>;
}

/**
 * 轮询结论：是否等到新终态，以及最后一轮成功读到的表（全败时为 null）。
 * 泛型 M 让调用方拿回自己传入的表形态（ChannelStatusMap 是 StatusMapView 的结构子集），
 * 免得在 setState 处再做一次收窄断言。
 */
export interface StatusPollResult<M extends StatusMapView = StatusMapView> {
  converged: boolean;
  map: M | null;
}

/** 默认轮次：8 轮（含首轮）。 */
export const TEST_STATUS_ATTEMPTS = 8;

/** 默认轮间间隔：1500ms（> system 1 秒节流窗，见模块头）。 */
export const TEST_STATUS_INTERVAL_MS = 1500;

function defaultSleep(ms: number): Promise<void> {
  return new Promise<void>((resolve) => {
    setTimeout(resolve, ms);
  });
}

/**
 * 单表收敛判定：目标频道有条目且 lastTs 为数字，且（无 prevTs，或比 prevTs 新）。
 *
 * prevTs 缺席 = 点击时该频道无条目：此后出现的任何条目都是新证据；prevTs 存在 = 以严格变新
 * 为准（同毫秒重投的 lastTs 可能相等，那次不等，下一轮或耗尽处理——不等旧结论冒充新结论）。
 */
export function statusConverged(
  map: StatusMapView,
  channelKey: string,
  prevTs: number | undefined,
): boolean {
  const entry = map[channelKey];
  if (entry === undefined || entry === null) return false;
  if (typeof entry.lastTs !== "number") return false;
  return prevTs === undefined || entry.lastTs > prevTs;
}

/**
 * 有限轮询：首轮即时读，之后每轮先睡间隔再读；读到收敛即停，耗尽返回最后所见。
 *
 * 单轮 fetch 抛错不抛给调用方（记为本轮无果，继续下一轮）； options.attempts<=0 时一次也不读
 * （调用方显式关掉轮询的形态，返回未收敛 null——与“全败”同形，调用方同样保留旧态）。
 */
export async function pollChannelStatus<M extends StatusMapView>(
  fetchStatus: () => Promise<M>,
  channelKey: string,
  prevTs: number | undefined,
  options: StatusPollOptions = {},
): Promise<StatusPollResult<M>> {
  const attempts = options.attempts ?? TEST_STATUS_ATTEMPTS;
  const intervalMs = options.intervalMs ?? TEST_STATUS_INTERVAL_MS;
  const sleep = options.sleep ?? defaultSleep;
  let latest: M | null = null;
  for (let round = 0; round < attempts; round += 1) {
    if (round > 0) await sleep(intervalMs);
    let map: M;
    try {
      map = await fetchStatus();
    } catch {
      continue;
    }
    latest = map;
    if (statusConverged(map, channelKey, prevTs)) return { converged: true, map };
  }
  return { converged: false, map: latest };
}

