/**
 * dsh-notifier — 弹出通知登记的判据（#769 阶段 3）。
 *
 * 「最多 5 条、超出关最旧、卸载只关自己登记的」原先散在 showNotification 与 disposer 里且无判据。
 * 上限是页面级语义（整个页面同时留几条弹窗），归属只决定「谁的清理关谁的弹窗」。
 */
import { afterEach, describe, expect, it } from "vitest";

import {
  closeNotificationsOf,
  NOTIFICATION_KEEP,
  trackNotification,
} from "../../src/client/notify/registry.ts";

function fake() {
  const closed: number[] = [];
  let index = 0;
  return {
    closed,
    make() {
      const id = index++;
      return {
        id,
        close(): void {
          closed.push(id);
        },
      };
    },
  };
}

/**
 * 注册表是模块级单例，逐用例隔离只能靠「谁登记谁清理」：用例结束时关掉本用例用过的全部令牌，
 * 免得上一条用例的残留被后面用例的上限淘汰踩到（那会让「超出上限」的判据看着红得莫名其妙）。
 */
const owners: object[] = [];
function owner(): object {
  const token: object = {};
  owners.push(token);
  return token;
}
afterEach(() => {
  for (const token of owners.splice(0)) closeNotificationsOf(token);
});

describe("弹出通知登记", () => {
  // 值锚：其余用例都以 NOTIFICATION_KEEP 为输入，常量改坏了它们照样绿，故显式钉住字面量。
  it("上限字面量是 5 条（值锚）", () => {
    expect(NOTIFICATION_KEEP).toBe(5);
  });

  it("未超上限时不动任何一条", () => {
    const f = fake();
    const token = owner();
    for (let i = 0; i < NOTIFICATION_KEEP; i += 1) trackNotification(f.make(), token);
    expect(f.closed).toEqual([]);
  });

  it("超出上限即关最旧的那一条", () => {
    const f = fake();
    const token = owner();
    for (let i = 0; i < NOTIFICATION_KEEP; i += 1) trackNotification(f.make(), token);
    trackNotification(f.make(), token);
    expect(f.closed).toEqual([0]);
    trackNotification(f.make(), token);
    expect(f.closed).toEqual([0, 1]);
  });

  // 硬编码档位：以常量驱动时把 NOTIFICATION_KEEP 改成 1 或 100 都不会红。这条把「6 条进、第 1 条
  // 被挤掉、页面剩 5 条」写成字面量，改常量必然打红。
  it("硬编码档位：连登 6 条即挤掉第 1 条、页面只剩 5 条", () => {
    const f = fake();
    const token = owner();
    for (let i = 0; i < 6; i += 1) trackNotification(f.make(), token);
    expect(f.closed).toEqual([0]);
    // 关掉本实例的登记就能数出「此刻页面上还剩几条」：只剩 1..5，共 5 条
    closeNotificationsOf(token);
    expect(f.closed).toEqual([0, 1, 2, 3, 4, 5]);
  });

  it("关掉本实例登记的通知并清空，再调一次不会重复关", () => {
    const f = fake();
    const token = owner();
    trackNotification(f.make(), token);
    trackNotification(f.make(), token);
    closeNotificationsOf(token);
    expect(f.closed).toEqual([0, 1]);
    closeNotificationsOf(token);
    expect(f.closed).toEqual([0, 1]);
  });

  it("closeNotificationsOf 只关自己登记的弹窗（别的实例不动）", () => {
    const a = fake();
    const b = fake();
    const tokenA = owner();
    const tokenB = owner();
    trackNotification(a.make(), tokenA);
    trackNotification(b.make(), tokenB);

    closeNotificationsOf(tokenA);

    expect(a.closed).toEqual([0]);
    expect(b.closed).toEqual([]);
    closeNotificationsOf(tokenB);
    expect(b.closed).toEqual([0]);
  });

  it("页面上限不分归属：甲乙交替登记超限时，挤掉的是页面上最旧的那条", () => {
    const a = fake();
    const b = fake();
    const tokenA = owner();
    const tokenB = owner();
    // 交替登记，第 6 条由乙登记：页面上最旧的是甲的第 1 条，超限淘汰不看归属
    trackNotification(a.make(), tokenA);
    trackNotification(b.make(), tokenB);
    trackNotification(a.make(), tokenA);
    trackNotification(b.make(), tokenB);
    trackNotification(a.make(), tokenA);
    trackNotification(b.make(), tokenB);

    expect(a.closed).toEqual([0]);
    expect(b.closed).toEqual([]);
    // 再关甲的登记：甲只剩 1、2 两条（第 0 条已被淘汰）
    closeNotificationsOf(tokenA);
    expect(a.closed).toEqual([0, 1, 2]);
    expect(b.closed).toEqual([]);
  });

  it("单条关闭抛错不阻塞其余关闭", () => {
    const f = fake();
    const token = owner();
    trackNotification(f.make(), token);
    trackNotification(
      {
        close(): void {
          throw new Error("already gone");
        },
      },
      token,
    );
    trackNotification(f.make(), token);
    expect(() => closeNotificationsOf(token)).not.toThrow();
    // 假通知的 id 由 make() 调用次数决定：两条成功的分别是 0 与 1，中间那条是抛错的内联对象
    expect(f.closed).toEqual([0, 1]);
  });
});

/**
 * dsh-notifier — 通知帧展示策略的判据（#769 阶段 2）。
 *
 * 这些判定原先与 Notification 构造、DOM 横幅、音频播放交织在一个函数里，因此没有一条判据。
 * 抽成纯函数后逐条钉住——尤其那三条「看起来可以简化、实际会改行为」的语义：缺 sound 字段的
 * 旧帧、playOnly + system 的归一、playOnly 不受可见性约束。
 */
import { describe, expect, it } from "vitest";

import {
  displayChannelOf,
  fallbackChannelOf,
  frameAccepted,
  soundPolicyOf,
} from "../../src/client/notify/policy.ts";

describe("soundPolicyOf：帧级声音策略", () => {
  it("缺 sound 字段的旧帧按「跟随系统默认」处理", () => {
    expect(soundPolicyOf(undefined, false)).toEqual({
      selfPlay: false,
      silent: false,
      tone: undefined,
    });
    expect(soundPolicyOf(null, false)).toEqual({ selfPlay: false, silent: false, tone: undefined });
    expect(soundPolicyOf("selfplay", false)).toEqual({
      selfPlay: false,
      silent: false,
      tone: undefined,
    });
  });

  it("silent 只静音、不自播", () => {
    expect(soundPolicyOf({ mode: "silent" }, false)).toEqual({
      selfPlay: false,
      silent: true,
      tone: undefined,
    });
  });

  it("selfplay 必须同时静音系统弹窗（否则与页内自播叠成双响）", () => {
    expect(soundPolicyOf({ mode: "selfplay", tone: "ding" }, false)).toEqual({
      selfPlay: true,
      silent: true,
      tone: "ding",
    });
  });

  it("tone 非字符串一律当没有（未知取值不给下游猜）", () => {
    expect(soundPolicyOf({ mode: "selfplay", tone: 7 }, false).tone).toBeUndefined();
    expect(soundPolicyOf({ mode: "selfplay", tone: null }, false).tone).toBeUndefined();
  });

  it("playOnly + system 归一为自播：没有弹窗实体时 OS 不会发声，不归一就是「0 弹 0 播」", () => {
    expect(soundPolicyOf({ mode: "system", tone: "bell" }, true)).toEqual({
      selfPlay: true,
      silent: true,
      tone: "bell",
    });
  });

  it("playOnly 不改变已明确的自播/静音策略", () => {
    expect(soundPolicyOf({ mode: "selfplay", tone: "pop" }, true).selfPlay).toBe(true);
    expect(soundPolicyOf({ mode: "silent" }, true)).toEqual({
      selfPlay: false,
      silent: true,
      tone: undefined,
    });
  });
});

describe("fallbackChannelOf / displayChannelOf：落点", () => {
  it("可见用横幅、隐藏改标题（看不见的页面上横幅没有意义）", () => {
    expect(fallbackChannelOf(false, "visible")).toBe("banner");
    expect(fallbackChannelOf(false, "hidden")).toBe("title");
  });

  it("playOnly 两条降级通道都不用", () => {
    expect(fallbackChannelOf(true, "visible")).toBe("none");
    expect(fallbackChannelOf(true, "hidden")).toBe("none");
  });

  it("可用且非 playOnly 才走系统通知", () => {
    expect(
      displayChannelOf({ playOnly: false, notificationUsable: true, visibility: "visible" }),
    ).toBe("notification");
    expect(
      displayChannelOf({ playOnly: true, notificationUsable: true, visibility: "hidden" }),
    ).toBe("none");
    expect(
      displayChannelOf({ playOnly: false, notificationUsable: false, visibility: "hidden" }),
    ).toBe("title");
  });
});

describe("frameAccepted：可见性门", () => {
  const base = { whenVisible: undefined, playOnly: undefined, visibility: "visible" };

  it("测试通知无条件处理（验证链路就是它的目的）", () => {
    expect(frameAccepted({ ...base, kind: "test" })).toBe(true);
    expect(
      frameAccepted({ kind: "test", whenVisible: false, playOnly: false, visibility: "visible" }),
    ).toBe(true);
  });

  it("页面可见时默认不提醒", () => {
    expect(frameAccepted({ ...base, kind: "done" })).toBe(false);
  });

  it("页面可见但帧说「可见时也弹」→ 处理", () => {
    expect(frameAccepted({ ...base, kind: "done", whenVisible: true })).toBe(true);
  });

  it("playOnly 不受可见性约束（纯声音提醒，不打扰界面）", () => {
    expect(frameAccepted({ ...base, kind: "done", playOnly: true })).toBe(true);
  });

  it("页面隐藏时一律处理（whenVisible 不参与）", () => {
    expect(
      frameAccepted({
        kind: "done",
        whenVisible: undefined,
        playOnly: undefined,
        visibility: "hidden",
      }),
    ).toBe(true);
  });
});

/**
 * dsh-notifier — 多标签租约的判据（#769 阶段 2）。
 *
 * 租约原先直接读写 localStorage 与 Date.now，判定因此测不到。端口化后三分支与三条异常路径
 * 都能穷举——其中「raw 为空串时仍要写入租约」是一条容易在重写时丢掉的语义：不写租约的话，
 * 每个标签都会各自抢占成功，多标签重复提醒。
 */
import { describe, expect, it } from "vitest";

import { claimMaster, MASTER_KEY, MASTER_LEASE_MS } from "../../src/client/notify/lease.ts";

/** 一份可断言的假 storage + 可控时钟。 */
function harness(initial: string | null, now = 1000) {
  const writes: string[] = [];
  let stored = initial;
  let clock = now;
  const ports = {
    now: () => clock,
    read: () => stored,
    write: (value: string) => {
      writes.push(value);
      stored = value;
    },
  };
  return {
    ports,
    writes,
    get stored() {
      return stored;
    },
    advance(ms: number) {
      clock += ms;
    },
  };
}

describe("claimMaster：谁弹、谁静默", () => {
  it("无租约时抢占成功并写入自己的租约", () => {
    const h = harness(null);
    expect(claimMaster("tab-a", h.ports)).toBe(true);
    expect(h.writes).toEqual([JSON.stringify({ id: "tab-a", ts: 1000 })]);
  });

  it("storage 里是空串时同样抢占并写入（旧实现把假值当「没有租约」）", () => {
    // 若改成 JSON.parse("")，会走异常分支返回 true 却不写租约 → 每个标签都各自放行
    const h = harness("");
    expect(claimMaster("tab-a", h.ports)).toBe(true);
    expect(h.writes).toHaveLength(1);
    expect(JSON.parse(h.stored as string).id).toBe("tab-a");
  });

  it("租约属于自己且在窗口内 → 续租并保留其它键", () => {
    const h = harness(JSON.stringify({ id: "tab-a", ts: 1000, extra: "keep" }));
    h.advance(500);
    expect(claimMaster("tab-a", h.ports)).toBe(true);
    expect(JSON.parse(h.writes[0] as string)).toEqual({ id: "tab-a", ts: 1500, extra: "keep" });
  });

  it("租约属于别的标签且未过期 → 静默，且不写任何东西", () => {
    const h = harness(JSON.stringify({ id: "tab-b", ts: 1000 }));
    h.advance(500);
    expect(claimMaster("tab-a", h.ports)).toBe(false);
    expect(h.writes).toEqual([]);
  });

  it("距租约写入 14999ms（窗口内 1ms，判定是严格小于）→ 仍归别的标签，静默且不写", () => {
    const h = harness(JSON.stringify({ id: "tab-b", ts: 1000 }));
    h.advance(14999);
    expect(claimMaster("tab-a", h.ports)).toBe(false);
    expect(h.writes).toEqual([]);
  });

  it("距租约写入 15000ms（恰好到期）→ 被抢占（与租约时长比较，不是「有租约就静默」）", () => {
    const h = harness(JSON.stringify({ id: "tab-b", ts: 1000 }));
    h.advance(15000);
    expect(claimMaster("tab-a", h.ports)).toBe(true);
    expect(JSON.parse(h.stored as string).id).toBe("tab-a");
  });

  it("可解析但形状非法（缺 id / ts 非数字 / 数组 / 标量）一律当无租约，抢占并写入", () => {
    for (const raw of [
      JSON.stringify({ ts: 1000 }),
      JSON.stringify({ id: "x", ts: "1" }),
      "[]",
      '"s"',
      JSON.stringify(null),
    ]) {
      const h = harness(raw);
      expect(claimMaster("tab-a", h.ports), raw).toBe(true);
      expect(h.writes, raw).toHaveLength(1);
    }
  });

  it("不可解析的 JSON 走异常路径放行，且不写租约（既有语义：宁重复提醒也不写坏存储）", () => {
    const h = harness("{oops");
    expect(claimMaster("tab-a", h.ports)).toBe(true);
    expect(h.writes).toEqual([]);
  });

  it("storage 读写抛错时放行（宁可在多标签下重复提醒，也不要彻底不提醒）", () => {
    const thrower = {
      now: () => 1,
      read: () => {
        throw new Error("denied");
      },
      write: () => {
        throw new Error("denied");
      },
    };
    expect(claimMaster("tab-a", thrower)).toBe(true);
  });

  it("storage 键是跨标签共享的那一个", () => {
    expect(MASTER_KEY).toBe("dsh-notifier:master");
  });

  it("MASTER_LEASE_MS 是字面量锚（防静默漂移，不是行为判据）", () => {
    // 行为用例都把常量当输入喂进去，改这个数字不会红；这条锚让「改数字」必须在测试里显式改一次。
    expect(MASTER_LEASE_MS).toBe(15000);
  });
});

